mapper.select:
SELECT model, COUNT(*) as count FROM ai_logs
WHERE success = 1 AND DATE(created_at) = #{date}
GROUP BY model ORDER BY count DESC

mapper.insert:
INSERT INTO ai_logs (model, provider, system_prompt_len, user_prompt_len, response_len,
                     duration_ms, success, error_msg
  , request_content
  , response_content
)
VALUES (#{model}, #{provider}, #{systemPromptLen}, #{userPromptLen}, #{responseLen},
        #{durationMs}, #{success}, #{errorMsg}
  , #{requestContent}
  , #{responseContent}
)
